#!/usr/bin/env python3
"""Gate C20 step 4: write results/analysis/consolidation/BIB_VERIFY_C20.md from /tmp/.../apply.json (made by c20_bib_apply.py) and lookup.json."""
import json, sys, re
sys.path.insert(0, "tests")
import c20_bibio as B
SCR = "/tmp/claude-1000/c20"
A = json.load(open(f"{SCR}/apply.json")); L = json.load(open(f"{SCR}/lookup.json"))
new = B.parse("paper/ref.bib")
FIELDS = ["author", "title", "journal", "booktitle", "volume", "number", "pages", "year", "doi", "howpublished", "note"]
o = ["# BIB_VERIFY_C20: ref.bib clean-up for print (Gate C20)", "",
     "Generated by `tests/c20_bib_report.py` from the Crossref and arXiv lookups (`tests/c20_bib_lookup.py`, `tests/c20_bib_apply.py`). Source of every new value is the URL in the **source** column; no field was invented. The previous file is `paper/archive/ref_c19.bib`.", "",
     "Match rule: a DOI lookup is authoritative; a title lookup is accepted only if exactly one non-preprint Crossref record has the same title (case, punctuation, spaces and parenthesised acronyms ignored); otherwise the entry is left as it was and marked **OPEN** with the candidates. Authors are given with initials. Titles carry brace protection for acronyms and proper nouns.", ""]
cnt = {"FIXED": 0, "UNCHANGED": 0, "OPEN": 0}
rows = []
for k, (before, after, status, why, src) in sorted(A["changed"].items()):
    nf = new[k]["fields"]; ch = []
    for f in FIELDS:
        b, a = before.get(f), nf.get(f)
        if B.plain(b or "").replace("--", "-") != B.plain(a or "").replace("--", "-"):
            ch.append(f"**{f}**: `{b if b else '(none)'}` -> `{a if a else '(none)'}`")
    if status == "FIXED" and not ch: status = "UNCHANGED"
    cnt[status] += 1
    extra = why
    r = L[k]
    if status == "OPEN":
        cs = [c for c in r["cands"] if c["type"] in ("proceedings-article", "journal-article")][:3]
        extra = "no exact title match; candidates: " + "; ".join(f"{c['doi']} ({c['container'][:50]}, {c['year']}, \"{c['title'][:70]}\", {len(c['authors'])} authors)" for c in cs)
        src = "https://api.crossref.org/works?query.bibliographic=" + re.sub(r"\s+", "+", B.plain(before.get("title", "")))
    rows.append((k, status, src, "<br>".join(ch) or "-", extra))
o += [f"## Summary: {cnt['FIXED']} FIXED, {cnt['UNCHANGED']} UNCHANGED, {cnt['OPEN']} OPEN (of {len(rows)} cited keys)", "", "| key | status | source | changed fields (before -> after) | note |", "|---|---|---|---|---|"]
for k, s, src, ch, ex in rows: o.append(f"| `{k}` | **{s}** | {src} | {ch} | {ex} |")
o += ["", "## OPEN keys and their candidates", ""]
for k, s, src, ch, ex in rows:
    if s == "OPEN": o.append(f"- `{k}`: {ex}")
o += ["- `nazaraliyev2024gpuvm` is FIXED for its author list (arXiv record, exact title) but its venue stays arXiv: Crossref lists a same-authors paper with a different title, *DREAM: Device-Driven Efficient Access to Virtual Memory* (ICS 2025, doi 10.1145/3721145.3725748, 3 authors), which may be the published version; not switched because the title differs.",
      "- `gu2020uvmbench`: authors filled from arXiv; no peer-reviewed record was found on Crossref (title search), so the arXiv venue stays.",
      "- `allen2024finegrain`: the Crossref title spells out *Unified Virtual Memory* where the old entry had *UVM*; the Crossref title is used (DOI lookup).",
      "- `go2023earlyadaptor`: Crossref's title has a typo (\"forProactive\"); the existing title is kept.",
      "- `choi2022gpuaware` and `parravicini2021dagpolyglot` switched from arXiv to IPDPSW 2022 and IPDPS 2021. The DOIs recorded in BIB_AUDIT (`10.1109/IPDPSW55747.2022.00164`, `10.1109/IPDPS49936.2021.00105`) differ from the ones Crossref returns for the exact titles (`10.1109/ipdpsw55747.2022.00097`, `10.1109/ipdps49936.2021.00020`); the Crossref values are used. `long2022dlprefetch` is JPDC 174 (2023), doi as in BIB_AUDIT.",
      "- `jain2020crac`: the DOI `10.5555/3433701.3433803` is not in Crossref (HTTP 404); the exact-title Crossref record is SC20, doi `10.1109/sc41405.2020.00081`, now used.", ""]
o += ["## Notes renamed to `x-note` (nothing printed from them)", "", f"{len(A['renamed'])} entries had a `note`/`annote`/`addendum`/`comment`; each is now `x-note` with its original text prefixed by the field name:", ""]
o += [f"- `{k}`" for k, _ in A["renamed"]]
o += ["", "## Notes kept (printed)", ""] + [f"- `{k}`: `{n}` (the Crossref article number of the journal paper; real bibliographic information)" for k, n in A["kept"]]
o += ["", "## Entries removed from `ref.bib` (kept in `paper/archive/ref_c19.bib`)", ""] + [f"- `{k}`: {w}" for k, w in A["removed"]]
o += ["", "BibTeX parses entries inside a `@Comment{...}` block (the `@comment` command does not skip its argument), so the old file defined both the arXiv key and the `_published` key; the text cites the original keys, which is why the arXiv entries were the ones printed. They now carry the peer-reviewed data and the `_published` duplicates are gone.", ""]
open("results/analysis/consolidation/BIB_VERIFY_C20.md", "w").write("\n".join(o))
print(cnt)
